<?php
require_once __DIR__.'/core/bootstrap.php';$user=require_login($pdo);
$rows=$pdo->query("SELECT un.name,un.city,COUNT(u.id) AS students,COALESCE(ROUND(AVG(u.rating),0),0) AS avg_rating,COALESCE(SUM((SELECT COUNT(DISTINCT s.problem_id) FROM submissions s WHERE s.user_id=u.id AND s.verdict='AC')),0) AS total_solves,MAX(u.rating) AS top_rating FROM universities un LEFT JOIN users u ON u.university=un.name GROUP BY un.name,un.city ORDER BY avg_rating DESC,total_solves DESC")->fetchAll();
$pageTitle='Universities';include __DIR__.'/includes/header.php';?>
<div class="page-head"><div><div class="eyebrow">Institution Analytics</div><h1>University Leaderboard</h1><p>Institution statistics are calculated dynamically from users and accepted submissions instead of relying on stale stored totals.</p></div></div>
<div class="grid grid-3"><?php foreach($rows as $i=>$r):?><div class="card card-pad feature-card"><div class="card-head"><span class="pill pill-neutral">#<?=$i+1?></span><small class="muted"><?=e($r['city']??'')?></small></div><h3><?=e($r['name'])?></h3><div class="grid grid-3" style="margin-top:18px"><div><small class="muted">Students</small><div style="font-size:21px;font-weight:800"><?=(int)$r['students']?></div></div><div><small class="muted">Solves</small><div style="font-size:21px;font-weight:800" class="text-green"><?=(int)$r['total_solves']?></div></div><div><small class="muted">Avg rating</small><div style="font-size:21px;font-weight:800" class="text-cyan"><?=(int)$r['avg_rating']?></div></div></div></div><?php endforeach;?></div>
